SOURCE='Unverified research leads: Smithsonian National Museum of Natural History, https://naturalhistory.si.edu/education/teaching-resources/life-science ; University of California Museum of Paleontology, https://ucmp.berkeley.edu/ . Exact claim-specific sources and species qualifications need independent verification.'
assert len(C)==11 and len({c['id'] for c in C})==11 and len({c['slug'] for c in C})==11
existing=[c['slug'] for c in C if (Path('src/demos/life')/c['slug']).exists()]
if existing:raise SystemExit('Refusing to overwrite existing lessons: '+', '.join(existing))
T='''"use client";
import { useState } from "react";
import { Lesson } from "@/kit/Lesson";
import { Control, Row } from "@/kit/controls";
type Data={question:string;options:string[];answer:number;why:string;caption:string;firstDescription:string};
const d:Data=__DATA__;
export default function Demo({slug}:{slug:string}){
 const [step,setStep]=useState(0);
 return <Lesson slug={slug} predict={{question:d.question,options:d.options,answer:d.answer}} exploreHint="Inspect both illustrated states." reveal={()=><p>{d.why}</p>}>
 {({locked,interact})=><div><svg viewBox="0 0 340 180" className="stage-svg" role="img" aria-label={step===0?"The illustrations are hidden until inspection.":step===1?d.firstDescription:d.why}>
 {step>=1&&<g>__FIRST__</g>}
 {step>=2&&<g>__SECOND__</g>}
 </svg><Row><Control style={{minHeight:44,minWidth:44}} disabled={locked||step!==0} onClick={()=>setStep(1)}>Inspect first</Control><Control style={{minHeight:44,minWidth:44}} disabled={locked||step!==1} onClick={()=>{setStep(2);interact()}}>Inspect second</Control></Row><p style={{textAlign:"center",color:"var(--muted)",fontSize:".8rem"}}>{d.caption}</p></div>}
 </Lesson>;
}
'''
manifest=[]
for c in C:
 slug=c['slug'];n=c['id'];shift=n%3;options=c['options'][shift:]+c['options'][:shift];answer=options.index(c['options'][0]);ro=c['ro'][shift:]+c['ro'][:shift];ra=ro.index(c['ro'][0]);firstlabels='; '.join(re.findall(r'>([^<>]+)</text>',c['a']));labels=re.findall(r'>([^<>]+)</text>',c['a']+c['b'])
 d={'question':c['q'],'options':options,'answer':answer,'why':c['why'],'caption':c['caption'],'firstDescription':'First state: '+firstlabels+'. Second state is hidden.'}
 demo=T.replace('__DATA__',json.dumps(d,ensure_ascii=False,indent=2)).replace('__FIRST__',c['a']).replace('__SECOND__',c['b'])
 out=Path('src/demos/life')/slug;out.mkdir(parents=True);(out/'Demo.tsx').write_text(demo)
 meta={'slug':slug,'title':c['title'],'hook':c['hook'],'domain':'life','concept':slug,'status':'draft','durationSec':60,'owner':{'categoryManager':'cm-life','builder':'demo-builder'},'learner':{'knows':['Animals have body structures and behaviors.'],'doesNotKnow':[c['why']]},'misconception':c['mis'],'objective':c['q'],'claims':[{'id':f'life.{slug}.c1','text':c['hook']+' '+c['q']+' '+c['why'],'support':'source','source':SOURCE,'status':'unverified'},{'id':f'life.{slug}.c2','text':'Diagram convention: '+c['caption']+' Diagram labels: '+'; '.join(labels)+'.','support':'convention','source':'Illustrative not-to-scale schematic; not an observed individual.','status':'unverified'},{'id':f'life.{slug}.c3','text':'Recall: '+c['rq']+' '+c['rw'],'support':'source','source':SOURCE,'status':'unverified'}],'confidence':'','recall':{'question':c['rq'],'options':ro,'answer':ra,'why':c['rw']},'evidence':{'qa':[],'simulatedLearner':[],'pairwise':[],'humanLearners':[]},'version':1}
 (out/'meta.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2)+'\n')
 review=Path('company/reviews')/slug;review.mkdir(parents=True)
 (review/'build.md').write_text(f'''# {slug}: build note, 2026-10-28\n\nDraft v1 for proposed curriculum item {n:03d}. The figure is an independently drawn schematic using a shared two-step comparison interaction. It is not a measured simulation or an image of an identified specimen. All claim-specific sources and anatomy are unverified.\n\n## Pre-flight v1\n\n1. Title and hook: “{c['title']}” / “{c['hook']}”; independent review should assess answer cues.\n2. Prediction options: {', '.join(options)}.\n3. The locked stage hides both images; controls are disabled before prediction.\n4. First and second illustrations remain visible when the second action unlocks reveal; a reviewer must check whether the picture supports the explanation.\n5. Intended path: Inspect first, then Inspect second. This is code inspection, not a browser result.\n6. No in-stage reset; reload behavior is untested.\n7. Strict 390 × 844 phone fit, text size, contrast, actual control dimensions, keyboard use and browser contract remain untested.\n\nExact supporting citations, taxonomy and overlap, visual pedagogy, accessibility, independent scientific accuracy and learner review remain open.\n''')
 manifest.append({'plan_id':n,'slug':slug})
Path('company/reviews/zoology-arthropod-extra/manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
print('Built',len(C),'distinct drafts:',', '.join(str(x['id']) for x in C))
